/bin/bash -lc "date -Is; rg -n -A12 -B6 'actionlint|workflow-security' .github/workflows Makefile scripts/gate_enforcement.json; printf '%s\\n' 'name: x' 'on:' '  schedule: []' 'jobs:' '  j:' '    runs-on: ubuntu-latest' '    steps:' '      - run: make kani' | actionlint -stdin-filename synthetic.yml -; printf 'actionlint-empty-schedule-rc=%s\\n' \""'$?"; env PYTHONDONTWRITEBYTECODE=1 python3 - <<'"'PY'
import sys
sys.path.insert(0, 'scripts')
import check_gate_enforcement as c
ctx={'step': {'run': 'make kani\\n'}, 'job_equals': {'runs-on':'ubuntu-latest'}, 'job_absent':['container','env','if','needs','strategy','defaults','continue-on-error']}
g={'id':'kani','make':'make kani','enforcement':'nightly','runs_in':'nightly.yml','polices_paths':['secure/src/**'],'required_context':ctx}
wf={'on':{'schedule':[]},'jobs':{'j':{'runs-on':'ubuntu-latest','steps':[{'run':'make kani\\n'}]}}}
print('triggers=', c.triggers(wf))
print('failures=', c.check_gate(g,_wf_override=wf))
PY"

